public static String getContentFromURL(String url) throws Exception {
        // Validasi host
        String host = validateHost(url);

        // Membuat URL baru dengan host yang sudah valid
        URL validatedUrl = new URL("http://" + host);

        // Mengambil konten dari URL
        return getContent(validatedUrl);
    }

    private static String validateHost(String url) {
        // Mengambil host dari URL
        String host = new URL(url).getHost();

        // Membersihkan host dari karakter tidak valid seperti spasi
        return host.replaceAll("\\s", "");
    }

    private static String getContent(URL url) throws Exception {
        // Menggunakan HttpURLConnection untuk mengambil konten dari URL
        HttpURLConnection connection = (HttpURLConnection) url.openConnection();
        connection.setRequestMethod("GET");
        connection.connect();

        int responseCode = connection.getResponseCode();
        if (responseCode == HttpURLConnection.HTTP_OK) {
            try (BufferedReader reader = new BufferedReader(new InputStreamReader(connection.getInputStream()))) {
                StringBuilder content = new StringBuilder();
                String line;
                while ((line = reader.readLine())!= null) {
                    content.append(line);
                }
                return content.toString();
            }
        } else {
            throw new Exception("Failed to retrieve content from URL. Response code: " + responseCode);
        }
    }
}
