import java.net.URL;
import java.io.BufferedReader;
import java.io.InputStreamReader;
import java.util.regex.Pattern;
import java.util.regex.Matcher;

public class ClassX {
    /**
     * שולף תוכן מ-URL שנוצר לאחר אימות המארח.
     * 
     * פונקציה זו מנקה את המארח על ידי בדיקה של תווים לא חוקיים כמו רווחים.
     * 
     * @param host The host to be sanitized.
     * @return A sanitized version of the host.
     */
    public static String sanitizeHost(String host) {
        // Regular expression to match invalid characters
        Pattern pattern = Pattern.compile("[^a-zA-Z0-9.-]");
        Matcher matcher = pattern.matcher(host);

        // Replace invalid characters with an empty string
        return matcher.replaceAll("");
    }

    /**
     * Reads content from a URL after sanitizing the host.
     * 
     * @param url The URL to read from.
     * @return The content of the URL as a string.
     * @throws Exception If an error occurs while reading the URL.
