                return getContent(cleanedUrl);
            } else {
                throw new IllegalArgumentException("Ongeldige host: " + host);
            }
        } catch (MalformedURLException e) {
            throw new IllegalArgumentException("Ongeldige URL: " + urlString, e);
        }
    }

    private static boolean isValidHost(String host) {
        // Regex voor een geldige hostnaam
        Pattern pattern = Pattern.compile("^([a-zA-Z0-9-]+\\.)+[a-zA-Z]{2,}$");
        Matcher matcher = pattern.matcher(host);
        return matcher.matches();
    }

    private static String sanitizeHost(String host) {
        // Verwijder spaties en andere ongeldige tekens
