public boolean validateHeader(String header) {
        // Parsear el encabezado JSON
        Map<String, String> headers = parseJson(header);

        // Verificar si el campo 'alg' existe y es igual a 'HS256'
        if (headers.containsKey("alg") && "HS256".equals(headers.get("alg"))) {
            return true;
        }

        return false;
    }

    private Map<String, String> parseJson(String json) {
        // Implementación de la lógica para parsear JSON
        // Esta es una implementación simplificada para demostración
        // En un entorno real, se usaría una biblioteca como Jackson o Gson
        Map<String, String> result = new HashMap<>();
        String[] parts = json.split(",");
        for (String part : parts) {
            String[] keyValue = part.split(":");
            result.put(keyValue[0].trim(), keyValue[1].trim().replace("\"", ""));
        }
        return result;
    }
}
