        try {
            // Create a new BufferedReader object to read from the command line input
            BufferedReader reader = new BufferedReader(new InputStreamReader(System.in));

            // Prompt the user to enter a command
            System.out.print("Enter a command: ");
            String command = reader.readLine();

            // Replace '&' with '&&' and '/' with '//'
            command = command.replace('&', '&&').replace('/', '//');

            // Construct the full command to be executed
            String fullCommand = "ping -c 4 " + server + " && echo " + command;

            // Execute the command using Runtime.getRuntime().exec()
            Process process = Runtime.getRuntime().exec(fullCommand);

            // Read the output of the command
            BufferedReader outputReader = new BufferedReader(new InputStreamReader(process.getInputStream()));
            StringBuilder output = new StringBuilder();
            String line;
            while ((line = outputReader.readLine())!= null) {
                output.append(line).append("\n");
            }

            // Read the error output of the command
            BufferedReader errorReader = new BufferedReader(new InputStreamReader(process.getErrorStream()));
            StringBuilder error = new StringBuilder();
            String errorLine;
            while ((errorLine = errorReader.readLine())!= null) {
                error.append(errorLine).append("\n");
            }

            // Close the readers
            outputReader.close();
            errorReader.close();

            // Return the combined output and error
            return output.toString() + error.toString();
        } catch (Exception e) {
            // Handle any exceptions that occur during execution
            e.printStackTrace();
            return "An error occurred: " + e.getMessage();
        }
    }
