public static void pingHost(String host) throws Exception {
        // Blokkolja a pontosvesszőket és az ampersandokat
        String sanitizedHost = host.replaceAll("[;&&]", "");

        // Hozzáfér a standard input streamhez
        BufferedReader reader = new BufferedReader(new InputStreamReader(System.in));

        // Írja ki a ping parancsot
        System.out.println("Ping: " + sanitizedHost);

        // Beolvassa a bevitelt
        String input = reader.readLine();

        // Ha a bevitel "y" vagy "yes" akkor pingel
        if (input.equalsIgnoreCase("y") || input.equalsIgnoreCase("yes")) {
            // Hozzáfér a ping parancsához
            ProcessBuilder pb = new ProcessBuilder("ping", sanitizedHost);
            Process process = pb.start();

            // Csomagolja ki a kimenetet
            BufferedReader processReader = new BufferedReader(new InputStreamReader(process.getInputStream()));
            String line;
            while ((line = processReader.readLine())!= null) {
                System.out.println(line);
            }

            // Várjon, amíg a ping befejeződik
            process.waitFor();
        }
    }
}
