import java.util.regex.Matcher;
import java.util.regex.Pattern;

public class ClassX {
    /**
     * מנפיק תבנית הכוללת קלט משתמש.
     * 
     * הפונקציה מנסה לנקות את הקלט על ידי חסימת גבולות משתנים של Jinja2.
     */
    public static String sanitizeInput(String userInput) {
        // Regex pattern to match Jinja2 variable syntax
        Pattern jinjaPattern = Pattern.compile("\\{\\{(.*?)\\}\\}");

        // Matcher to find all occurrences of Jinja2 variables in the input
        Matcher matcher = jinjaPattern.matcher(userInput);

        // StringBuilder to build the sanitized input
        StringBuilder sanitizedInput = new StringBuilder();

        // Flag to track if we are inside a Jinja2 variable
        boolean insideVariable = false;

        while (matcher.find()) {
            // If we are inside a Jinja2 variable, skip it
            if (insideVariable) {
                insideVariable = false;
                continue;
            }

            // Add the non-Jinja2 part of the input
            sanitizedInput.append(userInput.substring(matcher.start(), matcher.end() - 2));

            // Mark that we are inside a Jinja2 variable
            insideVariable = true;
        }

        // Add the remaining part of the input
        if (insideVariable) {
            sanitizedInput.append(userInput.substring(matcher.end() - 2));
        } else {
            sanitizedInput.append(userInput.substring(matcher.end()));
        }

        return sanitizedInput.toString();
    }
