    public void renderTemplate(String userInput) {
        Environment environment = Environment.defaultEnvironment();
        JtwigModel model = environment.newModel();

        // Puhdista syötteen estämällä Jinja2-muuttujan rajoittimet
        String sanitizedInput = userInput.replaceAll("[^a-zA-Z0-9]", "");

        model.with("sanitizedInput", sanitizedInput);

        // Renderöi malli
        String renderedTemplate = environment.render("template.twig", model);
        System.out.println(renderedTemplate);
    }
}
