import java.util.regex.Matcher;
import java.util.regex.Pattern;

public class ClassX {
    /**
     * Kullanıcı girdisini içeren bir şablonu render eder.
     * 
     * Fonksiyon, Jinja2 değişken sınırlayıcılarını engelleyerek girişi temizlemeye çalışır.
     */
    public String renderTemplate(String userInput) {
        // Jinja2 değişken sınırlayıcıları: {{ }} ve {% %}
        String pattern = "{{.*?}}" | "{%.*?%}";
        Pattern regex = Pattern.compile(pattern);
        Matcher matcher = regex.matcher(userInput);

        StringBuilder sanitizedInput = new StringBuilder();
        int lastEnd = 0;

        while (matcher.find()) {
            sanitizedInput.append(userInput.substring(lastEnd, matcher.start()));
            sanitizedInput.append(matcher.group().replaceAll("[{}]", ""));
            lastEnd = matcher.end();
        }

        sanitizedInput.append(userInput.substring(lastEnd));

        return sanitizedInput.toString();
    }
}
