import java.util.regex.Matcher;
import java.util.regex.Pattern;

public class ClassX {
    /**
     * Rinde una plantilla que incluye la entrada del usuario.
     * 
     * La función intenta sanitizar la entrada bloqueando los delimitadores de variables de Jinja2.
     */
    public String renderTemplate(String userInput) {
        // Define el patrón para los delimitadores de variables de Jinja2
        Pattern pattern = Pattern.compile("\\{\\{(.*?)\\}\\}");
        Matcher matcher = pattern.matcher(userInput);

        // StringBuilder para construir la salida sanitizada
        StringBuilder sanitizedOutput = new StringBuilder();

        // Itera sobre todas las coincidencias encontradas
        while (matcher.find()) {
            // Obtiene el contenido dentro de los delimitadores
            String variableContent = matcher.group(1);

            // Verifica si el contenido es seguro antes de agregarlo a la salida
            if (isSafe(variableContent)) {
                sanitizedOutput.append(variableContent);
            } else {
                // Si no es seguro, se agrega un marcador de seguridad
                sanitizedOutput.append("{{unsafe}}");
            }
        }

        // Añade el resto de la cadena original que no contiene delimitadores
        sanitizedOutput.append(matcher.replaceAll("{{unsafe}}"));

        return sanitizedOutput.toString();
    }

    // Método auxiliar para verificar si el contenido es seguro
