        // Blokkeer veelvoorkomende gevaarlijke trefwoorden
        String[] blockedWords = {"eval", "setTimeout", "setInterval", "new Function"};
        for (String word : blockedWords) {
            expression = expression.replace(word, "");
        }
        return expression;
    }
}
