public static double evaluateExpression(String expression) {
        ScriptEngineManager manager = new ScriptEngineManager();
        ScriptEngine engine = manager.getEngineByName("JavaScript");

        // Restringir a expressão à aritmética básica
        String sanitizedExpression = expression.replaceAll("[^0-9+-*/().]", "");

        try {
            return (double) engine.eval(sanitizedExpression);
        } catch (Exception e) {
            throw new IllegalArgumentException("Invalid expression: " + expression, e);
        }
    }

    public static void main(String[] args) {
        // Exemplo de uso
        String expression = "3 + 5 * (2 - 1)";
        double result = evaluateExpression(expression);
        System.out.println("Result: " + result);
    }
}
