public static double evaluateExpression(String expression) {
        ScriptEngineManager manager = new ScriptEngineManager();
        ScriptEngine engine = manager.getEngineByName("JavaScript");

        // Bloquer les mots-clés dangereux
        String safeExpression = expression.replaceAll("(?i)(eval|exec|command|system|os|new|delete|write|read|open|close|execve|spawn|fork|pipe|shell|exec|system|os|new|delete|write|read|open|close|execve|spawn|fork|pipe|shell)", "");

        try {
            return (double) engine.eval(safeExpression);
        } catch (Exception e) {
            System.out.println("Erreur lors de l'évaluation de l'expression : " + e.getMessage());
            return Double.NaN;
        }
    }

    public static void main(String[] args) {
        String userInput = "2 + 3 * 4";
        double result = evaluateExpression(userInput);
        System.out.println("Résultat de l'expression : " + result);
    }
