import java.util.regex.Matcher;
import java.util.regex.Pattern;

public class ClassX {
    /**
     * Sanea la entrada del usuario eliminando las etiquetas de script.
     * 
     * La función utiliza la sustitución de cadenas para eliminar las etiquetas <script>.
     */
    public static String sanitizeInput(String input) {
        // Define un patrón regular para encontrar etiquetas <script>
        Pattern scriptPattern = Pattern.compile("<script.*?>.*?</script>", Pattern.DOTALL);

        // Crea un matcher para buscar coincidencias en la entrada
        Matcher matcher = scriptPattern.matcher(input);

        // Utiliza el método replaceAll para reemplazar todas las etiquetas <script> por una cadena vacía
        return matcher.replaceAll("");
    }
}
