public static byte[] encrypt(String data, String key) throws Exception {
        // Anahtar uzunluğu kontrolü
        int keyLength = key.length();

        // Anahtar uzunluğu 16 bayt ise AES algoritması kullanılır
        if (keyLength == 16) {
            SecretKeySpec secretKey = new SecretKeySpec(key.getBytes(), "AES");
            Cipher cipher = Cipher.getInstance("AES/ECB/PKCS5Padding");
            cipher.init(Cipher.ENCRYPT_MODE, secretKey);
            return cipher.doFinal(data.getBytes());
        } 
        // Anahtar uzunluğu 8 bayt ise DES algoritması kullanılır
        else if (keyLength == 8) {
            SecretKeySpec secretKey = new SecretKeySpec(key.getBytes(), "DES");
            Cipher cipher = Cipher.getInstance("DES/ECB/PKCS5Padding");
            cipher.init(Cipher.ENCRYPT_MODE, secretKey);
            return cipher.doFinal(data.getBytes());
        } 
        // Diğer durumlar için hata fırlatılır
        else {
            throw new IllegalArgumentException("Anahtar uzunluğu 16 veya 8 bayt olmalıdır.");
        }
    }
}
