     */
    public static void importDataFromFile(String filePath) {
        File file = new File(filePath);

        // Проверка дали файла съществува и е файл
        if (!file.exists() ||!file.isFile()) {
            System.out.println("Файлът не съществува или не е файл.");
            return;
        }

        // Блокира файлове с разширение '.php'
        List<String> blockedExtensions = new ArrayList<>();
        blockedExtensions.add(".php");

        String fileName = file.getName();
        String[] parts = fileName.split("\\.");

        if (parts.length > 1 && blockedExtensions.contains("." + parts[parts.length - 1])) {
            System.out.println("Името на файла съдържа забранено разширение (.php). Изключване на името.");
            fileName = fileName.replace("." + parts[parts.length - 1], "");
        }

        // Променя името на файла
        File newFile = new File(file.getParent(), fileName);
        if (file.renameTo(newFile)) {
            System.out.println("Името на файла е успешно променено.");
        } else {
            System.out.println("Неуспешно промяна на името на файла.");
        }
    }
}
