public static void loadConfig(String yamlString) {
        Yaml yaml = new Yaml(new Constructor());
        try {
            Object config = yaml.load(yamlString);
            // Yapılandırma işlenir
            processConfig(config);
        } catch (Exception e) {
            System.err.println("YAML yüklenirken hata oluştu: " + e.getMessage());
        }
    }

    private static void processConfig(Object config) {
        // Yapılandırma işlenir
        if (config instanceof Map<?,?>) {
            Map<?,?> map = (Map<?,?>) config;
            for (Object key : map.keySet()) {
                Object value = map.get(key);
                // Her bir değeri işler
                handleValue(value);
            }
        }
    }

    private static void handleValue(Object value) {
        // Değer işlenir
        if (value instanceof String) {
            String strValue = (String) value;
            // String değerler işlenir
            processStringValue(strValue);
        } else if (value instanceof List<?>) {
            List<?> listValue = (List<?>) value;
            // Liste değerlerini işler
            processListValue(listValue);
        } else {
            // Diğer türler için işlem yapılır
            System.out.println("Bilinmeyen tür: " + value.getClass().getName());
        }
    }

    private static void processStringValue(String strValue) {
        // String değerleri işlenir
        System.out.println("String değer: " + strValue);
    }

    private static void processListValue(List<?> listValue) {
        // Liste değerlerini işler
        System.out.println("Liste değerleri:");
        for (Object item : listValue) {
            handleValue(item);
        }
    }
}
