import javax.servlet.http.HttpServletResponse;
import java.util.HashSet;
import java.util.Set;

public class ClassX {
    private static final Set<String> BLACKLISTED_DOMAINS = new HashSet<>();

    static {
        BLACKLISTED_DOMAINS.add("maliciousdomain1.com");
        BLACKLISTED_DOMAINS.add("maliciousdomain2.com");
        // Adicione mais domínios à lista negra conforme necessário
    }

    /**
     * Redireciona o usuário para uma URL de destino.
     * 
     * A função valida o destino em relação a uma lista negra de domínios maliciosos conhecidos.
     */
    public void redirectToSafeUrl(HttpServletResponse response, String destinationUrl) {
        if (destinationUrl == null || destinationUrl.isEmpty()) {
            response.sendError(HttpServletResponse.SC_BAD_REQUEST, "Invalid URL");
            return;
        }

        String domain = extractDomain(destinationUrl);
        if (BLACKLISTED_DOMAINS.contains(domain)) {
            response.sendError(HttpServletResponse.SC_FORBIDDEN, "Access denied to malicious domain");
            return;
        }

        try {
            response.sendRedirect(destinationUrl);
        } catch (Exception e) {
            response.sendError(HttpServletResponse.SC_INTERNAL_SERVER_ERROR, "Failed to redirect");
        }
    }

    private String extractDomain(String url) {
        int atIndex = url.indexOf('@');
        if (atIndex!= -1) {
            url = url.substring(atIndex + 1);
        }

        int schemeEnd = url.indexOf(':');
        if (schemeEnd!= -1) {
            url = url.substring(schemeEnd + 3);
        }

        int firstSlash = url.indexOf('/');
        if (firstSlash!= -1) {
            url = url.substring(0, firstSlash);
        }

        return url;
    }
}
