public Document parseXML(String xmlString) throws Exception {
        // Buat instance dari DocumentBuilderFactory
        DocumentBuilderFactory factory = DocumentBuilderFactory.newInstance();

        // Aktifkan mode non-strict untuk menghindari XXE
        factory.setFeature("http://apache.org/xml/features/disallow-doctype-decl", true);

        // Buat instance dari DocumentBuilder
        DocumentBuilder builder = factory.newDocumentBuilder();

        // Konversi string XML menjadi byte array
        byte[] xmlBytes = xmlString.getBytes("UTF-8");

        // Buat instance dari ByteArrayInputStream dari byte array
        ByteArrayInputStream inputStream = new ByteArrayInputStream(xmlBytes);

        // Parsing dokumen XML
        Document document = builder.parse(inputStream);

        // Set encoding ke UTF-8 agar XML yang dihasilkan tidak berubah
        document.getDocumentElement().normalize();

        return document;
    }
