public static String fetchContentFromURL(String urlString) {
        try {
            // URL objektum létrehozása
            URL url = new URL(urlString);

            // HttpURLConnection objektum létrehozása
            HttpURLConnection connection = (HttpURLConnection) url.openConnection();

            // Hozzáférés engedélyezése
            connection.setRequestMethod("GET");
            connection.setConnectTimeout(5000); // 5 másodperc
            connection.setReadTimeout(5000); // 5 másodperc

            // Végigmegyünk a válaszban
            if (connection.getResponseCode() == HttpURLConnection.HTTP_OK) {
                BufferedReader reader = new BufferedReader(new InputStreamReader(connection.getInputStream()));
                StringBuilder content = new StringBuilder();

                String line;
                while ((line = reader.readLine())!= null) {
                    content.append(line).append("\n");
                }

                reader.close();
                return content.toString();
            } else {
                throw new RuntimeException("Failed to retrieve content from URL: " + urlString + ". HTTP response code: " + connection.getResponseCode());
            }
        } catch (Exception e) {
            throw new RuntimeException("Error fetching content from URL: " + urlString, e);
        }
    }
}
