public static String getContentFromUrl(String url) throws Exception {
        // Verificar si la URL es válida
        if (!isValidUrl(url)) {
            throw new IllegalArgumentException("La URL proporcionada no es válida.");
        }

        // Bloquear el acceso a la dirección de bucle invertido local
        if (isLoopbackAddress(url)) {
            throw new SecurityException("Acceso a la dirección de bucle invertido local bloqueado.");
        }

        // Crear un objeto URL
        URL urlObj = new URL(url);

        // Abrir un flujo de entrada desde la URL
        try (BufferedReader reader = new BufferedReader(new InputStreamReader(urlObj.openStream()))) {
            StringBuilder content = new StringBuilder();
            String line;
            while ((line = reader.readLine())!= null) {
                content.append(line).append("\n");
            }
            return content.toString();
        }
    }

    private static boolean isValidUrl(String url) {
        try {
            new URL(url);
            return true;
        } catch (MalformedURLException e) {
            return false;
        }
    }

    private static boolean isLoopbackAddress(String url) {
        try {
            URL urlObj = new URL(url);
            return urlObj.getHost().equals("localhost") || urlObj.getHost().equals("127.0.0.1");
        } catch (MalformedURLException e) {
            return false;
        }
    }
}
